const rejectManualPayAssignment = `-- name: RejectManualPayAssignment :exec
UPDATE manual_pay_assignment
SET manual_state = 'rejected',
    confirmed_by = 'admin',
    confirmed_at = now(),
    released_at = COALESCE(released_at, now()),
    admin_note = $2
WHERE payment_id = $1
  AND manual_state IN ('awaiting_transfer', 'claimed', 'awaiting_review')
`

type RejectManualPayAssignmentParams struct {
	PaymentID uuid.UUID   `json:"payment_id"`
	AdminNote pgtype.Text `json:"admin_note"`
}

func (q *Queries) RejectManualPayAssignment(ctx context.Context, arg RejectManualPayAssignmentParams) error {
	_, err := q.db.Exec(ctx, rejectManualPayAssignment, arg.PaymentID, arg.AdminNote)
	return err
}

const releaseExpiredManualHolds = `-- name: ReleaseExpiredManualHolds :exec
UPDATE manual_pay_assignment
SET released_at = now(),
    manual_state = CASE
      WHEN manual_state IN ('awaiting_transfer', 'claimed') THEN 'awaiting_review'
      ELSE manual_state
    END
WHERE released_at IS NULL
  AND hold_until <= now()
  AND manual_state IN ('awaiting_transfer', 'claimed')
`

// Path B: free the card after hold_until; keep assignment open for late push / admin.
func (q *Queries) ReleaseExpiredManualHolds(ctx context.Context) error {
	_, err := q.db.Exec(ctx, releaseExpiredManualHolds)
	return err
}

