const updateManualPayCard = `-- name: UpdateManualPayCard :one
UPDATE manual_pay_card
SET pan_full = $2,
    pan_last4 = $3,
    holder_name = $4,
    sort_order = $5,
    enabled = $6,
    updated_at = now()
WHERE id = $1
RETURNING id, network, pan_full, pan_last4, holder_name, sort_order, enabled, created_at, updated_at
`

type UpdateManualPayCardParams struct {
	ID         uuid.UUID `json:"id"`
	PanFull    string    `json:"pan_full"`
	PanLast4   string    `json:"pan_last4"`
	HolderName string    `json:"holder_name"`
	SortOrder  int32     `json:"sort_order"`
	Enabled    bool      `json:"enabled"`
}

func (q *Queries) UpdateManualPayCard(ctx context.Context, arg UpdateManualPayCardParams) (ManualPayCard, error) {
	row := q.db.QueryRow(ctx, updateManualPayCard,
		arg.ID,
		arg.PanFull,
		arg.PanLast4,
		arg.HolderName,
		arg.SortOrder,
		arg.Enabled,
	)
	var i ManualPayCard
	err := row.Scan(
		&i.ID,
		&i.Network,
		&i.PanFull,
		&i.PanLast4,
		&i.HolderName,
		&i.SortOrder,
		&i.Enabled,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const upsertManualTgSettings = `-- name: UpsertManualTgSettings :one
UPDATE manual_tg_settings
SET api_id_enc = CASE WHEN $1::bool THEN $2 ELSE api_id_enc END,
    api_hash_enc = CASE WHEN $3::bool THEN $4 ELSE api_hash_enc END,
    session_enc = CASE WHEN $5::bool THEN $6 ELSE session_enc END,
    humo_bot_username = CASE WHEN $7::bool THEN $8 ELSE humo_bot_username END,
    updated_at = now()
WHERE id = 1
RETURNING id, api_id_enc, api_hash_enc, session_enc, humo_bot_username,
          last_test_ok, last_test_at, last_test_detail, updated_at
`

type UpsertManualTgSettingsParams struct {
	SetApiID        bool        `json:"set_api_id"`
	ApiIDEnc        pgtype.Text `json:"api_id_enc"`
	SetApiHash      bool        `json:"set_api_hash"`
	ApiHashEnc      pgtype.Text `json:"api_hash_enc"`
	SetSession      bool        `json:"set_session"`
	SessionEnc      pgtype.Text `json:"session_enc"`
	SetBotUsername  bool        `json:"set_bot_username"`
	HumoBotUsername string      `json:"humo_bot_username"`
}

func (q *Queries) UpsertManualTgSettings(ctx context.Context, arg UpsertManualTgSettingsParams) (ManualTgSetting, error) {
	row := q.db.QueryRow(ctx, upsertManualTgSettings,
		arg.SetApiID,
		arg.ApiIDEnc,
		arg.SetApiHash,
		arg.ApiHashEnc,
		arg.SetSession,
		arg.SessionEnc,
		arg.SetBotUsername,
		arg.HumoBotUsername,
	)
	var i ManualTgSetting
	err := row.Scan(
		&i.ID,
		&i.ApiIDEnc,
		&i.ApiHashEnc,
		&i.SessionEnc,
		&i.HumoBotUsername,
		&i.LastTestOk,
		&i.LastTestAt,
		&i.LastTestDetail,
		&i.UpdatedAt,
	)
	return i, err
}
